<script lang="ts">
 let {title,data,unit='',t,lang='de',comparisonLabel='',valueLabel='uxActual'}:{title:string;data:{label:string;value:number;comparison?:number}[];unit?:string;t:(s:string)=>string;lang?:string;comparisonLabel?:string;valueLabel?:string}=$props();
 let max=$derived(Math.max(1,...data.flatMap(d=>[d.value,d.comparison??0])));let showComparison=$state(true);
 const format=(value:number)=>new Intl.NumberFormat(lang,{maximumFractionDigits:2}).format(value);
</script>
<section class="card chart-card"><div class="chart-heading"><h2>{title}</h2><span class="pill">{unit}</span></div>{#if data.length}<div class="legend"><span><i></i>{t(valueLabel)}</span>{#if comparisonLabel}<button class="legend-toggle" aria-pressed={showComparison} onclick={()=>showComparison=!showComparison}><i class="comparison"></i>{t(comparisonLabel)}</button>{/if}</div><div class="bars" role="img" aria-label={title}>{#each data as row}<div class="bar-row"><div class="bar-label"><span title={row.label}>{row.label}</span><strong>{format(row.value)} <small>{unit}</small></strong></div><div class="bar-track"><div class="bar" style:width={(Math.max(0,row.value)/max*100)+'%'}></div></div>{#if comparisonLabel&&showComparison}<div class="bar-track comparison-track"><div class="bar comparison" style:width={(Math.max(0,row.comparison??0)/max*100)+'%'}></div></div><span class="comparison-value">{t(comparisonLabel)}: {format(row.comparison??0)} {unit}</span>{/if}</div>{/each}</div><details class="chart-data"><summary>{t('uxChartData')}</summary><table><thead><tr><th>{t('name')}</th><th>{t(valueLabel)}</th>{#if comparisonLabel}<th>{t(comparisonLabel)}</th>{/if}</tr></thead><tbody>{#each data as row}<tr><td>{row.label}</td><td>{format(row.value)} {unit}</td>{#if comparisonLabel}<td>{format(row.comparison??0)} {unit}</td>{/if}</tr>{/each}</tbody></table></details>{:else}<p class="empty-state">{t('uxEmptyHint')}</p>{/if}</section>
<style>.chart-heading{display:flex;align-items:center;justify-content:space-between;gap:12px}.chart-heading h2{margin:0}.legend{display:flex;gap:18px;align-items:center;margin:16px 0 20px;color:var(--muted);font-size:11px}.legend>span,.legend-toggle{display:inline-flex;align-items:center;gap:7px}.legend i{width:8px;height:8px;border-radius:2px;background:var(--brand)}.legend-toggle{min-height:30px;color:var(--muted);background:transparent;padding:4px;border:0;font-size:11px;font-weight:500}.legend-toggle[aria-pressed=false]{opacity:.4}.bars{display:grid;gap:15px}.bar-label{display:flex;justify-content:space-between;gap:12px;font-size:12px;margin-bottom:7px}.bar-label>span{white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.bar-label strong{font-size:12px;white-space:nowrap;font-variant-numeric:tabular-nums}.bar-label small{color:var(--muted);font-weight:400}.bar-track{height:9px;border-radius:3px;background:#f0f4f1;overflow:hidden}.bar{height:100%;background:var(--brand);border-radius:3px;min-width:0}.comparison-track{margin-top:4px;height:5px}.comparison{background:#718e9b!important}.comparison-value{display:block;text-align:right;font-size:10px;color:var(--muted);margin-top:4px}.chart-data{margin-top:14px}.chart-data summary{font-size:11px;color:var(--muted)}table{width:100%;font-size:12px;text-align:left;border-collapse:collapse}td,th{padding:8px;border-bottom:1px solid var(--line)}
</style>
